import { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { api, formatApiError } from "../lib/api";
import { useAuth } from "../lib/auth";
import { toast } from "sonner";
import LoadingSpinner from "../components/LoadingSpinner";
import ConfirmDialog from "../components/ConfirmDialog";
import TextEditDialog from "../components/TextEditDialog";
import { ArrowUpRight, Compass, Music, Radio } from "lucide-react";

export default function Explore() {
  const [params] = useSearchParams();
  const artistFilter = params.get("artist") || "";
  const [tab, setTab] = useState("albums");
  const [albums, setAlbums] = useState([]);
  const [artists, setArtists] = useState([]);
  const [tracks, setTracks] = useState([]);
  const [explore, setExplore] = useState(null);
  const { user } = useAuth();
  const [actionLoadingId, setActionLoadingId] = useState(null);
  const [selectedArtist, setSelectedArtist] = useState(null);
  const [deleteArtist, setDeleteArtist] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    Promise.all([
      api.get("/albums"),
      api.get("/artists"),
      api.get("/tracks"),
      api.get("/relationships/explore").catch(() => null),
    ])
      .then(([a, ar, t, ex]) => {
        setAlbums(a.data);
        setArtists(ar.data);
        setTracks(t.data);
        setExplore(ex?.data || null);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const tabs = [
    { id: "albums", label: "Album Universes" },
    { id: "artists", label: "Artists" },
    { id: "tracks", label: "Tracks" },
  ];

  // Filter albums by artist if ?artist= param is present
  const filteredAlbums = artistFilter
    ? albums.filter((a) => a.artist_name?.toLowerCase().includes(artistFilter.toLowerCase()))
    : albums;

  const featuredAlbums = explore?.featured_albums || [];
  const canonicalAlbums = explore?.recent_albums || [];
  const canonicalArtists = explore?.artists || [];

  if (loading) {
    return (
      <div className="max-w-[1480px] mx-auto px-6 py-20 text-center meta-ink">
        <LoadingSpinner size={24} />
        <div className="mt-4">loading explore…</div>
      </div>
    );
  }

  return (
    <div className="max-w-[1480px] mx-auto px-6 py-12">
      <div className="meta-ink mb-3">section 02 · the index</div>
      <h1 className="font-display font-black text-5xl md:text-7xl tracking-tighter">Explore.</h1>
      <p className="font-editorial italic text-xl md:text-2xl mt-3 max-w-2xl">no algorithm. no feed. choose a door.</p>
      {explore && (
        <div className="flex flex-wrap gap-4 mt-4">
          <span className="tag-chip"><strong>{explore.total_albums || albums.length}</strong> albums</span>
          <span className="tag-chip"><strong>{explore.total_artists || artists.length}</strong> artists</span>
          {featuredAlbums.length > 0 && (
            <span className="tag-chip accent" style={{ background: 'var(--acid)' }}>
              <strong>{featuredAlbums.length}</strong> featured worlds
            </span>
          )}
        </div>
      )}

      {/* FEATURED ROW — live graph data */}
      {featuredAlbums.length > 0 && (
        <section className="mt-10">
          <div className="meta-ink mb-3">curated worlds</div>
          <div className="flex gap-4 overflow-x-auto pb-4 -mx-6 px-6 snap-x">
            {featuredAlbums.map((a) => (
              <Link key={a.id} to={`/album/${a.id}`} className="snap-start flex-shrink-0 w-64 group">
                <div className="aspect-[4/3] relative grain brutal-shadow" style={{ background: a.color || '#111' }}>
                  <div className="absolute inset-4 border-2 border-[var(--ink)] p-4 flex flex-col justify-between group-hover:bg-black/10 transition-colors">
                    <span className="meta-ink mix-blend-multiply">{a.year}</span>
                    <span className="font-display font-black text-2xl tracking-tighter text-[var(--ink)] mix-blend-multiply">{a.title.toLowerCase()}</span>
                  </div>
                </div>
                <div className="mt-2">
                  <div className="font-display font-bold text-sm">{a.artist_name || a.artist_id}</div>
                  <p className="font-editorial italic text-sm text-[var(--ink-mute)] line-clamp-2">{a.universe_tagline}</p>
                </div>
              </Link>
            ))}
          </div>
        </section>
      )}

      {artistFilter && (
        <div className="mt-6 p-4 brutal-card-static bg-[var(--acid)]">
          <div className="meta-ink">filtered by artist</div>
          <div className="font-display font-bold text-xl mt-1">{artistFilter} · {filteredAlbums.length} albums</div>
          <Link to="/explore" className="underline text-sm mt-1 inline-block">clear filter</Link>
        </div>
      )}

      <div className="mt-8 flex flex-wrap gap-2 border-b-2 border-[var(--ink)] pb-3">
        {tabs.map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)} data-testid={`explore-tab-${t.id}`}
            className={`px-4 py-2 font-display font-bold text-sm border-2 border-[var(--ink)] ${tab===t.id?'bg-[var(--ink)] text-[var(--parchment)]':'bg-white hover:bg-[var(--parchment-deep)]'}`}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ALBUMS TAB — main + canonical */}
      {tab === "albums" && (
        <div className="mt-8">
          {/* Canonical recent albums */}
          {canonicalAlbums.length > 0 && (
            <div className="mb-10">
              <div className="meta-ink mb-4">recently ingested · canonical graph</div>
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
                {canonicalAlbums.map((a) => (
                  <Link key={a.id} to={`/album/${a.id}`} className="brutal-card p-0 overflow-hidden" data-testid={`canonical-album-${a.id}`}>
                    <div className="aspect-[5/4] relative grain" style={{ background: a.color }}>
                      <div className="absolute inset-4 border-2 border-[var(--ink)] p-4 flex flex-col justify-between">
                        <span className="meta-ink mix-blend-multiply">{a.year}</span>
                        <span className="font-display font-black text-3xl tracking-tighter text-[var(--ink)] mix-blend-multiply">{a.title.toLowerCase()}</span>
                      </div>
                    </div>
                    <div className="p-5 border-t-2 border-[var(--ink)]">
                      <div className="meta-ink">{a.artist_name || a.artist_id}</div>
                      <p className="font-editorial italic text-lg mt-1">{a.universe_tagline}</p>
                    </div>
                  </Link>
                ))}
              </div>
            </div>
          )}

          {/* Legacy albums */}
          <div>
            <div className="meta-ink mb-4">{canonicalAlbums.length > 0 ? 'legacy collection' : 'all albums'}</div>
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
              {filteredAlbums.map((a) => (
                <Link key={a.id} to={`/album/${a.id}`} className="brutal-card p-0 overflow-hidden" data-testid={`album-card-${a.id}`}>
                  <div className="aspect-[5/4] relative grain" style={{ background: a.color }}>
                    <div className="absolute inset-4 border-2 border-[var(--ink)] p-4 flex flex-col justify-between">
                      <span className="meta-ink mix-blend-multiply">{a.year}</span>
                      <span className="font-display font-black text-3xl tracking-tighter text-[var(--ink)] mix-blend-multiply">{a.title.toLowerCase()}</span>
                    </div>
                  </div>
                  <div className="p-5 border-t-2 border-[var(--ink)]">
                    <div className="meta-ink">{a.artist_id}</div>
                    <p className="font-editorial italic text-lg mt-1">{a.universe_tagline}</p>
                  </div>
                </Link>
              ))}
            </div>
            {filteredAlbums.length === 0 && <p className="meta-ink mt-6">no albums yet. seed the graph via admin.</p>}
          </div>
        </div>
      )}

      {/* ARTISTS TAB — legacy + canonical */}
      {tab === "artists" && (
        <div className="mt-8">
          {canonicalArtists.length > 0 && (
            <div className="mb-10">
              <div className="meta-ink mb-4">canonical artists</div>
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
                {canonicalArtists.map((a) => (
                  <div key={a.id} className="brutal-card-static p-6">
                    <div className="meta-ink">{a.scene || 'artist'}</div>
                    <div className="font-display font-black text-3xl tracking-tighter mt-2">{a.name}</div>
                    <p className="font-editorial italic text-lg mt-2">{a.tagline || a.bio?.slice(0, 120) || ''}</p>
                    <Link to={`/explore?artist=${encodeURIComponent(a.name)}`} className="inline-flex items-center gap-1 text-sm underline mt-3">
                      view albums <ArrowUpRight size={12} />
                    </Link>
                  </div>
                ))}
              </div>
            </div>
          )}
          
          <div className="meta-ink mb-4">{canonicalArtists.length > 0 ? 'legacy artists' : 'all artists'}</div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5 mt-8">
            {artists.map((a) => (
              <div key={a.id} className="brutal-card-static p-6" data-testid={`artist-card-${a.id}`}>
                <div className="meta-ink">{a.scene} · {a.era}</div>
                <div className="font-display font-black text-3xl tracking-tighter mt-2">{a.name}</div>
                <p className="font-editorial italic text-lg mt-2">{a.tagline}</p>
                {user?.role === "admin" && (
                  <div className="mt-3 flex gap-2">
                    <button className="brutal-btn" onClick={() => setSelectedArtist(a)} disabled={actionLoadingId !== null && actionLoadingId !== a.id}>
                      {actionLoadingId === a.id ? <><LoadingSpinner size={16} className="inline-block" /> <span className="ml-2">Saving</span></> : "Edit"}
                    </button>
                    <button className="brutal-btn" onClick={() => setDeleteArtist(a)} disabled={actionLoadingId !== null && actionLoadingId !== a.id}>
                      {actionLoadingId === a.id ? <><LoadingSpinner size={16} className="inline-block" /> <span className="ml-2">Deleting</span></> : "Delete"}
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* TRACKS TAB — unchanged */}
      {tab === "tracks" && (
        <div className="divide-y-2 divide-[var(--ink)] border-2 border-[var(--ink)] mt-8 brutal-shadow bg-white">
          {tracks.map((t, i) => (
            <Link key={t.id} to={`/track/${t.id}`} className="flex items-center gap-4 px-5 py-3 hover:bg-[var(--parchment-deep)]" data-testid={`track-row-${t.id}`}>
              <span className="meta-ink w-10">{String(i+1).padStart(2,'0')}</span>
              <span className="font-display font-bold text-lg flex-1">{t.title}</span>
              <span className="meta-ink">{t.album_id}</span>
              <span className="meta-ink">{t.duration}</span>
              <span className="tag-chip">{t.lore_count} lore</span>
            </Link>
          ))}
        </div>
      )}

      <TextEditDialog
        open={Boolean(selectedArtist)}
        title="Edit artist"
        label="Artist name"
        value={selectedArtist?.name}
        placeholder="Artist name"
        loading={actionLoadingId === selectedArtist?.id}
        onCancel={() => setSelectedArtist(null)}
        onSave={async (name) => {
          if (!selectedArtist) return;
          setActionLoadingId(selectedArtist.id);
          try {
            await api.put(`/artists/${selectedArtist.id}`, { name });
            const response = await api.get("/artists");
            setArtists(response.data);
            toast.success("Artist updated");
            setSelectedArtist(null);
          } catch (error) {
            toast.error(formatApiError(error.response?.data?.detail));
          } finally {
            setActionLoadingId(null);
          }
        }}
      />

      <ConfirmDialog
        open={Boolean(deleteArtist)}
        title="Delete artist"
        description={deleteArtist ? `Delete ${deleteArtist.name}? This action cannot be undone.` : ""}
        confirmLabel="Delete"
        cancelLabel="Cancel"
        danger
        loading={actionLoadingId === deleteArtist?.id}
        onCancel={() => setDeleteArtist(null)}
        onConfirm={async () => {
          if (!deleteArtist) return;
          setActionLoadingId(deleteArtist.id);
          try {
            await api.delete(`/artists/${deleteArtist.id}`);
            setArtists((current) => current.filter((artist) => artist.id !== deleteArtist.id));
            toast.success("Artist deleted");
            setDeleteArtist(null);
          } catch (error) {
            toast.error(formatApiError(error.response?.data?.detail));
          } finally {
            setActionLoadingId(null);
          }
        }}
      />
    </div>
  );
}
